const alert = $('Webhook desde MS5 Alerts').first().json.body;
const aiBrief = $input.first().json?.emergencyParagraph || alert.recommendedAction;

const iconMap = {
  FROST_ALERT: '❄️🚨 ALERTA CRÍTICA DE HELADA EN SANDÍA',
  HEAT_AND_DROUGHT_SHOCK: '🔥💧 ALERTA CRÍTICA: GOLPE DE CALOR Y SEQUÍA RADICULAR',
  SUDDEN_NDVI_DROP: '🛰️🥀 ALERTA SATELITAL: CAÍDA BRUSCA DE VIGOR (NDVI)'
};

const header = iconMap[alert.ruleCode] || '🚨 ALERTA AGRONÓMICA AGROSAT AI';
const m = alert.metrics || {};
const lines = [
  header,
  '',
  '👨‍🌾 *Agricultor:* ' + alert.farmer.fullName,
  '🍉 *Parcela:* ' + alert.parcel.parcelAlias,
  '📍 *Ubicación:* ' + alert.parcel.centroid.lat + ', ' + alert.parcel.centroid.lon,
  '',
  '📊 *Indicadores Detectados:*'
];

if (m.ambientTempC !== undefined) lines.push('• 🌡️ Temp. Ambiente: *' + m.ambientTempC + ' °C*');
if (m.soilMoisture20cmPct !== undefined) lines.push('• 💧 Humedad Suelo (20cm): *' + m.soilMoisture20cmPct + '%*');
if (m.soilMoisture40cmPct !== undefined) lines.push('• 💧 Humedad Suelo (40cm): *' + m.soilMoisture40cmPct + '%*');
if (m.currentNdvi !== undefined) lines.push('• 🛰️ NDVI Sector Afectado: *' + m.currentNdvi + '* (Caída: -' + m.ndviDrop + ')');

lines.push('');
lines.push('🧠 *Diagnóstico Rápido del Agrónomo Virtual (DeepSeek):*');
lines.push('_' + String(aiBrief).replace(/[_*[\]`]/g, '') + '_');
lines.push('');
lines.push('⏱️ _Emitido: ' + new Date(alert.triggeredAt).toLocaleString('es-MX') + '_');

return [{ json: { chatId: alert.farmer.telegramChatId, text: lines.join('\n') } }];
